package com.example.phonicsgarden.util

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import com.example.phonicsgarden.R
import dagger.hilt.android.qualifiers.ApplicationContext
import java.util.concurrent.ConcurrentHashMap
import javax.inject.Inject
import javax.inject.Singleton

/**
 * [SoundEffects] backed by Android's SoundPool, which is designed for short, low-latency sounds.
 * The WAV files in res/raw are generated by `tools/generate_sounds.py` (original, synthesized).
 */
@Singleton
class SoundPoolEffects @Inject constructor(
    @ApplicationContext context: Context
) : SoundEffects {

    private val resources = mapOf(
        SoundEffect.POP to R.raw.pop,
        SoundEffect.CHOMP to R.raw.chomp,
        SoundEffect.CHIME to R.raw.chime,
        SoundEffect.SOFT to R.raw.soft,
        SoundEffect.BLOOM to R.raw.bloom,
        SoundEffect.FANFARE to R.raw.fanfare
    )

    private val pool = SoundPool.Builder()
        .setMaxStreams(3)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()

    private val soundIds = HashMap<SoundEffect, Int>()

    /** Sound ids that have finished loading (loading is asynchronous). */
    private val loaded: MutableSet<Int> = ConcurrentHashMap.newKeySet()

    init {
        pool.setOnLoadCompleteListener { _, soundId, status -> if (status == 0) loaded.add(soundId) }
        resources.forEach { (effect, resId) -> soundIds[effect] = pool.load(context, resId, 1) }
    }

    override fun play(effect: SoundEffect) {
        val id = soundIds[effect] ?: return
        if (id in loaded) pool.play(id, VOLUME, VOLUME, 1, 0, 1f)
    }

    private companion object {
        const val VOLUME = 0.8f
    }
}
